// What the dispatch and pause scripts share: arguments, the config, `gh api`, and the
// discovery of the repos attached to the session, and the check that each can be
// pushed to.
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const FOOTER =
  "\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_";
export const PAUSE_LABEL = "workshop-paused";

export const arg = (name, dflt) => {
  const i = process.argv.indexOf(name);
  return i > 0 ? process.argv[i + 1] : dflt;
};
export const flag = (name) => process.argv.includes(name);

const run = (cmd, args, input) =>
  execFileSync(cmd, args, {
    encoding: "utf8",
    input,
    maxBuffer: 1 << 26,
    // Keep stderr out of the log: a failure still throws with it attached,
    // and an expected 422 stays quiet.
    stdio: ["pipe", "pipe", "pipe"],
  });
export const api = (path, ...rest) =>
  JSON.parse(run("gh", ["api", path, ...rest]) || "null");
// --paginate --slurp yields one array per page.
export const all = (path) => api(path, "--paginate", "--slurp").flat();
export const post = (path, body, method = "POST") =>
  run("gh", ["api", "-X", method, path, "--input", "-"], JSON.stringify(body));
export const names = (x) => x.labels.map((l) => (typeof l === "string" ? l : l.name));

/**
 * The workshop config: `{digest, checkouts, repos: [{repo, name, path}]}`. `--config`
 * picks the file holding the digest repo (default: workshop.json next to this skill).
 * The repos are every GitHub clone directly under checkouts, which is `--checkouts`,
 * $WORKSHOP_CHECKOUTS, or the folder holding the clone the run started in (the
 * working directory itself when that isn't a clone): the repos attached to the
 * session. `--repos a/b,c/d` limits the run to some of them.
 */
export const loadConfig = () => {
  const here = dirname(fileURLToPath(import.meta.url));
  const file = arg("--config", join(here, "..", "workshop.json"));
  const cfg = JSON.parse(readFileSync(file, "utf8"));
  if (!cfg.digest) throw new Error(`${file} needs a "digest" repo`);
  const checkouts = resolve(
    arg("--checkouts") ?? process.env.WORKSHOP_CHECKOUTS ?? startedIn(),
  );
  const found = readdirSync(checkouts, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(checkouts, d.name, ".git")))
    .map((d) => {
      const path = join(checkouts, d.name);
      let url;
      try {
        url = run("git", ["-C", path, "remote", "get-url", "origin"]);
      } catch {
        return null;
      }
      const repo = url.trim().match(/github\.com[/:]([^/]+\/[^/]+?)(?:\.git)?\/?$/i)?.[1];
      return repo && { repo, name: repo.split("/")[1], path };
    })
    .filter(Boolean)
    .sort((a, b) => a.repo.localeCompare(b.repo));
  const only = arg("--repos")?.split(",").map((r) => r.trim().toLowerCase());
  const repos = found.filter((r) => !only || only.includes(r.repo.toLowerCase()));
  const unknown = (only ?? []).filter((o) => !repos.some((r) => r.repo.toLowerCase() === o));
  if (unknown.length)
    throw new Error(
      `--repos names repos not checked out under ${checkouts}: ${unknown.join(", ")}. Attach them to the session.`,
    );
  if (!repos.length)
    throw new Error(`No GitHub clone under ${checkouts}: attach a repo to the session.`);
  return { digest: cfg.digest, checkouts, repos };
};

// The folder holding the clone the run started in, or the working directory itself
// when the run didn't start in a clone (a session with several repos may start
// above them).
const startedIn = () => {
  try {
    return dirname(run("git", ["rev-parse", "--show-toplevel"]).trim());
  } catch {
    return process.cwd();
  }
};

/**
 * Stops the run, naming every attached repo that can't be pushed to. A dry-run
 * push writes nothing. A repo attached read-only is a mistake to fix, not one to
 * skip quietly.
 */
export const preflight = (repos) => {
  const problems = [];
  for (const r of repos) {
    try {
      run("git", [
        "-C",
        r.path,
        "push",
        "--dry-run",
        "--quiet",
        "origin",
        "HEAD:refs/heads/claude/workshop-push-check",
      ]);
    } catch (e) {
      problems.push(
        `${r.repo}: can't push (${(e.stderr || e.message).toString().trim().split("\n").at(-1)})`,
      );
    }
  }
  if (problems.length)
    throw new Error(
      `The workshop can't run on every attached repo:\n- ${problems.join("\n- ")}\nGive the session push access to the repo, or detach it.`,
    );
};

// Runs main(), turning a thrown error into one clear line and exit code 1.
export const main = (fn) => {
  try {
    fn();
  } catch (e) {
    console.error(`workshop: ${e.message}`);
    process.exit(1);
  }
};
